/**
 * Example 2: Multi-Tool Orchestration
 *
 * The agent autonomously uses Glob, Bash, and Read tools to
 * accomplish a multi-step task.
 *
 * Run: npx tsx examples/02-multi-tool.ts
 */
import { createAgent } from '../src/index.js'

async function main() {
  console.log('--- Example 2: Multi-Tool Orchestration ---\n')

  const agent = createAgent({
    model: process.env.CODEANY_MODEL || 'claude-sonnet-4-6',
    maxTurns: 15,
  })

  for await (const event of agent.query(
    'Do these steps: ' +
    '1) Use Glob to find all .ts files in src/ (pattern "src/*.ts"). ' +
    '2) Use Bash to count lines in src/agent.ts with `wc -l`. ' +
    '3) Give a brief summary.',
  )) {
    const msg = event as any

    if (msg.type === 'assistant') {
      for (const block of msg.message?.content || []) {
        if (block.type === 'tool_use') {
          console.log(`[${block.name}] ${JSON.stringify(block.input).slice(0, 100)}`)
        }
        if (block.type === 'text' && block.text.trim()) {
          console.log(`\n${block.text}`)
        }
      }
    }

    if (msg.type === 'result') {
      console.log(`\n--- ${msg.subtype} | ${msg.usage?.input_tokens}/${msg.usage?.output_tokens} tokens ---`)
    }
  }
}

main().catch(console.error)

/**
 * Example 7: Custom Tools
 *
 * Shows how to define and use custom tools alongside built-in tools.
 *
 * Run: npx tsx examples/07-custom-tools.ts
 */
import { createAgent, getAllBaseTools, defineTool } from '../src/index.js'

const weatherTool = defineTool({
  name: 'GetWeather',
  description: 'Get current weather for a city. Returns temperature and conditions.',
  inputSchema: {
    type: 'object',
    properties: {
      city: { type: 'string', description: 'City name (e.g., "Tokyo", "London")' },
    },
    required: ['city'],
  },
  isReadOnly: true,
  isConcurrencySafe: true,
  async call(input) {
    const temps: Record<string, number> = {
      tokyo: 22, london: 14, beijing: 25, 'new york': 18, paris: 16,
    }
    const temp = temps[input.city?.toLowerCase()] ?? 20
    return `Weather in ${input.city}: ${temp}°C, partly cloudy`
  },
})

const calculatorTool = defineTool({
  name: 'Calculator',
  description: 'Evaluate a mathematical expression. Use ** for exponentiation.',
  inputSchema: {
    type: 'object',
    properties: {
      expression: { type: 'string', description: 'Math expression (e.g., "42 * 17 + 3", "2 ** 10")' },
    },
    required: ['expression'],
  },
  isReadOnly: true,
  isConcurrencySafe: true,
  async call(input) {
    try {
      const result = Function(`'use strict'; return (${input.expression})`)()
      return `${input.expression} = ${result}`
    } catch (e: any) {
      return { data: `Error: ${e.message}`, is_error: true }
    }
  },
})

async function main() {
  console.log('--- Example 7: Custom Tools ---\n')

  const builtinTools = getAllBaseTools()
  const allTools = [...builtinTools, weatherTool, calculatorTool]

  const agent = createAgent({
    model: process.env.CODEANY_MODEL || 'claude-sonnet-4-6',
    maxTurns: 10,
    tools: allTools,
  })

  console.log(`Loaded ${allTools.length} tools (${builtinTools.length} built-in + 2 custom)\n`)

  for await (const event of agent.query(
    'What is the weather in Tokyo and London? Also calculate 2**10 * 3. Be brief.',
  )) {
    const msg = event as any
    if (msg.type === 'assistant') {
      for (const block of msg.message?.content || []) {
        if (block.type === 'tool_use') {
          console.log(`[${block.name}] ${JSON.stringify(block.input)}`)
        }
        if (block.type === 'text' && block.text.trim()) {
          console.log(`\n${block.text}`)
        }
      }
    }
    if (msg.type === 'result') {
      console.log(`\n--- ${msg.subtype} ---`)
    }
  }
}

main().catch(console.error)

'use client'
import Image from 'next/image'
import React, { useState } from 'react'
import {
  motion,
  useTransform,
  AnimatePresence,
  useMotionValue,
  useSpring,
} from 'framer-motion'

export const AnimatedTooltip = ({
  items,
  size = 40,
  spacingClass = '-mr-4',
}: {
  items: {
    id: number
    name: string
    designation: string
    image: string
  }[]
  size?: number
  spacingClass?: string
}) => {
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null)
  const springConfig = { stiffness: 100, damping: 5 }
  const x = useMotionValue(0) // going to set this value on mouse move
  // rotate the tooltip
  const rotate = useSpring(
    useTransform(x, [-100, 100], [-45, 45]),
    springConfig,
  )
  // translate the tooltip
  const translateX = useSpring(
    useTransform(x, [-100, 100], [-50, 50]),
    springConfig,
  )
  const handleMouseMove = (event: any) => {
    const halfWidth = event.target.offsetWidth / 2
    x.set(event.nativeEvent.offsetX - halfWidth) // set the x value, which is then used in transform and rotate
  }

  return (
    <>
      {items.map((item, idx) => (
        <div
          className={`${spacingClass} relative group`}
          key={item.name}
          onMouseEnter={() => setHoveredIndex(item.id)}
          onMouseLeave={() => setHoveredIndex(null)}
        >
          <AnimatePresence mode="popLayout">
            {hoveredIndex === item.id && (
              <motion.div
                initial={{ opacity: 0, y: 20, scale: 0.6 }}
                animate={{
                  opacity: 1,
                  y: 0,
                  scale: 1,
                  transition: {
                    type: 'spring',
                    stiffness: 260,
                    damping: 10,
                  },
                }}
                exit={{ opacity: 0, y: 20, scale: 0.6 }}
                style={{
                  translateX: translateX,
                  rotate: rotate,
                  whiteSpace: 'nowrap',
                }}
                className="absolute -top-16 -left-full translate-x-1/2 flex text-xs  flex-col items-center justify-center rounded-md bg-black z-50 shadow-xl px-4 py-2"
              >
                <div className="absolute inset-x-10 z-30 w-[20%] -bottom-px bg-gradient-to-r from-transparent via-emerald-500 to-transparent h-px " />
                <div className="absolute left-10 w-[40%] z-30 -bottom-px bg-gradient-to-r from-transparent via-sky-500 to-transparent h-px " />
                <div className="font-bold text-white relative z-30 text-base">
                  {item.name}
                </div>
                <div className="text-white text-xs">{item.designation}</div>
              </motion.div>
            )}
          </AnimatePresence>
          <Image
            onMouseMove={handleMouseMove}
            height={100}
            width={100}
            src={item.image}
            alt={item.name}
            style={{ width: size, height: size }}
            className="object-cover !m-0 !p-0 object-top rounded-full border-2 group-hover:scale-105 group-hover:z-30 border-white bg-white dark:bg-white relative transition duration-500"
          />
        </div>
      ))}
    </>
  )
}

import { ControllerDecorator as Controller, ToolDecorator as Tool, PromptDecorator as Prompt, z, ExecutionContext } from '@nitrostack/core';
import { trackToolExecution } from '../../telemetry/langfuse.service.js';

@Controller('continuum')
export class ValidationTools {

  @Tool({
    name: 'validate_heuristic',
    description: 'Validates a manufacturing heuristic mathematically against sensor datasets. Exposes the rule and data to the Orchestrator LLM to compute statistical significance.',
    inputSchema: z.object({
      heuristicId: z.string().optional().describe('The ID of the heuristic'),
      rule: z.string().describe('The Structured JSON AST rule to validate (as a JSON string)'),
      datasetUri: z.string().optional().describe('URI to the sensor logs')
    }),
  })
  async validateHeuristic(input: any, ctx: ExecutionContext) {
    return trackToolExecution('validate_heuristic', input, async () => {
      let ruleStr = typeof input.rule === 'string' ? input.rule : JSON.stringify(input.rule);

      if (!ruleStr || ruleStr === 'expected value' || ruleStr.trim() === '' || ruleStr === '{}') {
        return {
          success: false,
          error: "Invalid rule. Please provide a specific Structured JSON AST rule to validate."
        };
      }
      if (!input.datasetUri || input.datasetUri === 'expected value' || input.datasetUri.trim() === '') {
        return {
          success: false,
          error: "Validation requires a dataset. Please provide a dataset URI (e.g., neon://sensor_logs)."
        };
      }

      ctx.logger.info(`Requested validation for structured rule`);

      // Instead of using Gemini locally, we return the payload so the
      // Orchestrator LLM (Claude inside NitroStudio) can use its own tokens
      return {
        success: true,
        instruction: `Please act as an expert Data Scientist. Calculate the statistical significance of the following Structured JSON AST rule against the dataset. Provide your reasoning and confidence score in a clear, formatted response.`,
        ruleToValidate: input.rule,
        datasetContext: input.datasetUri,
        message: 'Payload returned successfully. Waiting for Orchestrator LLM to compute validation.'
      };
    });
  }

  @Prompt({
    name: 'data_scientist_subagent',
    description: 'Instructs the LLM to act as a strict Data Scientist.',
    arguments: [],
  })
  async getDataScientistPrompt() {
    return {
      messages: [
        {
          role: 'user',
          content: `You are the Data Scientist Subagent. Your job is to take a Structured JSON AST Rule and a dataset context, and calculate the statistical significance (e.g., p-value, correlation) to determine if the rule is 'Accepted' or 'Rejected'.`
        }
      ]
    };
  }
}

/**
 * SEP-2106 full JSON Schema 2020-12 for tools (modern path only).
 *
 * The legacy path converts Zod with `target: 'jsonSchema7'` and inlines refs
 * (`$refStrategy: 'none'`), forcing `type: "object"` on both input and output —
 * unchanged so 2025-era clients never see unexpected keywords.
 *
 * On 2026-07-28 tool schemas are lifted to full JSON Schema 2020-12:
 * - input keeps an object root but may carry `oneOf`/`anyOf`/`allOf`,
 *   conditionals, and `$ref`/`$defs`
 * - output is unrestricted (not forced to an object)
 * - external `$ref` URIs are never auto-dereferenced and schema depth is bounded
 *
 * @module
 */

import { z } from 'zod';

/** JSON Schema object (loose). */
export type JsonSchemaObject = Record<string, unknown>;

/** Maximum schema nesting depth accepted on the modern path (DoS guard). */
export const MAX_SCHEMA_DEPTH = 64;

function isZodSchema(schema: unknown): schema is z.ZodSchema {
  return !!schema && typeof schema === 'object' && '_def' in (schema as object);
}

/**
 * Bound the depth of a JSON schema object, replacing anything deeper than
 * `maxDepth` with a permissive `{}` so a pathological `$defs` graph cannot blow
 * the stack or the validator. External `$ref` URIs are left intact but are
 * never dereferenced by NitroStack.
 */
export function boundSchemaDepth(value: unknown, maxDepth = MAX_SCHEMA_DEPTH, depth = 0): unknown {
  if (value === null || typeof value !== 'object') {
    return value;
  }
  if (depth >= maxDepth) {
    return {};
  }
  if (Array.isArray(value)) {
    return value.map((v) => boundSchemaDepth(v, maxDepth, depth + 1));
  }
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
    out[k] = boundSchemaDepth(v, maxDepth, depth + 1);
  }
  return out;
}

/**
 * Convert a Zod or JSON schema to JSON Schema 2020-12 for the modern era,
 * preserving composition (`oneOf`/`anyOf`/`allOf`), conditionals, and
 * `$ref`/`$defs`.
 *
 * @param schema - Zod schema or a pre-built JSON schema.
 * @param opts.root - `'input'` forces an object root (spec requirement for tool
 *   input); `'output'` leaves the schema unrestricted.
 */
export async function convertToModernJsonSchema(
  schema: unknown,
  opts: { root: 'input' | 'output' },
): Promise<JsonSchemaObject> {
  let json: JsonSchemaObject;

  if (isZodSchema(schema)) {
    try {
      const mod = await import('zod-to-json-schema');
      const zodToJsonSchema = (mod as { zodToJsonSchema?: unknown; default?: unknown }).zodToJsonSchema
        || (mod as { default?: unknown }).default;
      // 2019-09 target keeps $ref/$defs and composition (closest widely-supported
      // preset to 2020-12 in zod-to-json-schema); root strategy emits $defs.
      json = (zodToJsonSchema as (s: unknown, o: unknown) => JsonSchemaObject)(schema, {
        target: 'jsonSchema2019-09',
        $refStrategy: 'root',
      });
      // Advertise the 2020-12 dialect explicitly (SEP-2106). zod-to-json-schema
      // stamps a 2019-09 `$schema`; the emitted keywords are 2020-12-compatible
      // for tool schemas, so relabel to the revision the spec requires.
      json.$schema = 'https://json-schema.org/draft/2020-12/schema';
    } catch {
      json = { type: 'object', properties: {}, additionalProperties: true };
    }
  } else if (schema && typeof schema === 'object') {
    json = { ...(schema as JsonSchemaObject) };
  } else {
    json = {};
  }

  json = boundSchemaDepth(json) as JsonSchemaObject;

  if (opts.root === 'input') {
    // Input schema root must be an object per spec; composition/refs are allowed
    // alongside it but the root type stays 'object'.
    if (!('type' in json) && !('$ref' in json)) {
      json.type = 'object';
    } else if (json.type && json.type !== 'object') {
      json.type = 'object';
    }
    // Allow additionalProperties on input schemas so clients (ChatGPT, Codex, Studio)
    // passing _meta and other contextual parameters are not rejected with INVALID_ARGUMENT (-32602).
    json.additionalProperties = true;
  }

  return json;
}

import type { z } from 'zod/v4'
import type { ToolPermissionContext } from '../../Tool.js'
import { splitCommand_DEPRECATED } from '../../utils/bash/commands.js'
import type { PermissionResult } from '../../utils/permissions/PermissionResult.js'
import type { BashTool } from './BashTool.js'

const ACCEPT_EDITS_ALLOWED_COMMANDS = [
  'mkdir',
  'touch',
  'rm',
  'rmdir',
  'mv',
  'cp',
  'sed',
] as const

type FilesystemCommand = (typeof ACCEPT_EDITS_ALLOWED_COMMANDS)[number]

function isFilesystemCommand(command: string): command is FilesystemCommand {
  return ACCEPT_EDITS_ALLOWED_COMMANDS.includes(command as FilesystemCommand)
}

function validateCommandForMode(
  cmd: string,
  toolPermissionContext: ToolPermissionContext,
): PermissionResult {
  const trimmedCmd = cmd.trim()
  const [baseCmd] = trimmedCmd.split(/\s+/)

  if (!baseCmd) {
    return {
      behavior: 'passthrough',
      message: 'Base command not found',
    }
  }

  // In Accept Edits mode, auto-allow filesystem operations
  if (
    toolPermissionContext.mode === 'acceptEdits' &&
    isFilesystemCommand(baseCmd)
  ) {
    return {
      behavior: 'allow',
      updatedInput: { command: cmd },
      decisionReason: {
        type: 'mode',
        mode: 'acceptEdits',
      },
    }
  }

  return {
    behavior: 'passthrough',
    message: `No mode-specific handling for '${baseCmd}' in ${toolPermissionContext.mode} mode`,
  }
}

/**
 * Checks if commands should be handled differently based on the current permission mode
 *
 * This is the main entry point for mode-based permission logic.
 * Currently handles Accept Edits mode for filesystem commands,
 * but designed to be extended for other modes.
 *
 * @param input - The bash command input
 * @param toolPermissionContext - Context containing mode and permissions
 * @returns
 * - 'allow' if the current mode permits auto-approval
 * - 'ask' if the command needs approval in current mode
 * - 'passthrough' if no mode-specific handling applies
 */
export function checkPermissionMode(
  input: z.infer<typeof BashTool.inputSchema>,
  toolPermissionContext: ToolPermissionContext,
): PermissionResult {
  // Skip if in bypass mode (handled elsewhere)
  if (toolPermissionContext.mode === 'bypassPermissions') {
    return {
      behavior: 'passthrough',
      message: 'Bypass mode is handled in main permission flow',
    }
  }

  // Skip if in dontAsk mode (handled in main permission flow)
  if (toolPermissionContext.mode === 'dontAsk') {
    return {
      behavior: 'passthrough',
      message: 'DontAsk mode is handled in main permission flow',
    }
  }

  const commands = splitCommand_DEPRECATED(input.command)

  // Check each subcommand
  for (const cmd of commands) {
    const result = validateCommandForMode(cmd, toolPermissionContext)

    // If any command triggers mode-specific behavior, return that result
    if (result.behavior !== 'passthrough') {
      return result
    }
  }

  // No mode-specific handling needed
  return {
    behavior: 'passthrough',
    message: 'No mode-specific validation required',
  }
}

export function getAutoAllowedCommands(
  mode: ToolPermissionContext['mode'],
): readonly string[] {
  return mode === 'acceptEdits' ? ACCEPT_EDITS_ALLOWED_COMMANDS : []
}

